/* wp-custom-css */

/* ==== BANDERAS Y ESTILO GOBERNA PRO ==== */

/* Base de todos los botones */
a.flag {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 0 0 0 12px;
  background: #ffffff;
  border-radius: 999px;
  box-shadow: 0 4px 12px rgba(2, 58, 90, 0.1);
  font-weight: 500;
  color: #023A5A;
  transition: all 0.2s ease-in-out;
}

/* Animación hover */
a.flag:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 18px rgba(2, 58, 90, 0.2);
}

/* Icono bandera base */
a.flag::before {
  content: "";
  width: 18px;
  height: 12px;
  border-radius: 2px;
  box-shadow: 0 0 0 1px rgba(0,0,0,.15);
  flex: 0 0 18px;
}

/* 🇵🇪 Perú */
a.flag-pe::before {
  background: linear-gradient(90deg, #D91023 0 33.33%, #FFFFFF 33.33% 66.66%, #D91023 66.66% 100%);
}

/* 🇧🇴 Bolivia */
a.flag-bo::before {
  background: linear-gradient(#D52B1E 0 33.33%, #FFD700 33.33% 66.66%, #007934 66.66% 100%);
}

/* 🇲🇽 México */
a.flag-mx::before {
  background: linear-gradient(90deg, #006847 0 33.33%, #FFFFFF 33.33% 66.66%, #CE1126 66.66% 100%);
}

/* 🇪🇨 Ecuador */
a.flag-ec::before {
  background: linear-gradient(#FCD116 0 50%, #003893 50% 75%, #CE1126 75% 100%);
}

/* 🌍 Global */
a.flag-global::before {
  content: "🌍";
  width: auto;
  height: auto;
  box-shadow: none;
  background: none;
  font-size: 16px;
  line-height: 1;
  filter: drop-shadow(0 1px 1px rgba(0,0,0,.15));
}

/* Texto grisado si está inactivo o no tiene número (por si acaso) */
a.flag:has([disabled]), a.flag[href=""] {
  opacity: 0.6;
  pointer-events: none;
}

