/* Player de testimonios (imita el embed de cms.goberna.club) */
.ak-vsec .ak-vp{position:relative;overflow:hidden;aspect-ratio:1/1;touch-action:pan-y}
.ak-vsec .ak-vp>.elementor-widget-html{position:absolute!important;inset:0;width:100%!important;max-width:none!important;margin:0!important;z-index:2;pointer-events:none}
.ak-vsec .ak-vp>.elementor-widget-html>.elementor-widget-container{height:100%}
.ak-vplayer{position:absolute;inset:0;display:none;overflow:hidden;background:#15262F;pointer-events:auto;container-type:inline-size;font-family:Inter,Arial,sans-serif}
.ak-vp.ak-on .ak-vplayer{display:block}
.ak-vbl{position:absolute;inset:-40px;background:center/cover no-repeat;filter:blur(26px) brightness(.5)}
.ak-vplayer video{position:absolute;top:0;bottom:0;left:50%;transform:translateX(-50%);height:100%;width:auto;max-width:none;aspect-ratio:9/16;object-fit:cover;display:block;background:#000;cursor:pointer;box-shadow:0 0 40px rgba(0,0,0,.5)}
.ak-vbb{position:absolute;left:0;right:0;bottom:0;padding:30px 16px 12px;background:linear-gradient(to top,rgba(10,22,40,.85),rgba(10,22,40,0));transition:opacity .3s}
.ak-vplayer.ak-idle .ak-vbb{opacity:0}
.ak-vpg{height:16px;display:flex;align-items:center;cursor:pointer;margin-bottom:6px}
.ak-vtr{position:relative;width:100%;height:5px;border-radius:3px;background:rgba(255,255,255,.14)}
.ak-vfl{position:absolute;left:0;top:0;height:100%;width:0;border-radius:3px;background:linear-gradient(90deg,#FFBB03,#FFD466);box-shadow:0 0 10px rgba(255,187,3,.5)}
.ak-vth{position:absolute;top:50%;left:0;width:13px;height:13px;border-radius:50%;border:2px solid #fff;background:#FFBB03;transform:translate(-50%,-50%)}
.ak-vrow{display:flex;justify-content:space-between;align-items:center}
.ak-vrow>div{display:flex;align-items:center;gap:4px}
.ak-vplayer button,.ak-vp .ak-vnav,.ak-vp .ak-vbig{all:unset;box-sizing:border-box;cursor:pointer}
.ak-vcb{width:30px;height:30px;display:grid!important;place-items:center;border-radius:6px;color:rgba(255,255,255,.85)}
.ak-vcb:hover{background:rgba(255,255,255,.1)}
.ak-vcb svg{width:18px;height:18px;fill:currentColor}
.ak-vtm{color:#fff;font:600 11px/1 Inter,Arial,sans-serif;font-variant-numeric:tabular-nums;background:rgba(10,22,40,.6);border:1px solid rgba(255,187,3,.25);border-radius:6px;padding:5px 9px;margin-left:6px}
.ak-vtm span{opacity:.65}
@container (max-width:360px){.ak-vbb{padding:20px 8px 6px}.ak-vtm{font-size:10px;padding:4px 7px}.ak-vcb{width:26px;height:26px}.ak-vcb svg{width:15px;height:15px}.ak-vpg{margin-bottom:2px}}
.ak-vp .ak-vnav,.ak-vswh{display:none}
.ak-vdots{display:none}
/* Un solo video: sin flechas, aviso de deslizar ni puntos */
.ak-vsec.ak-solo .ak-vp .ak-vnav,.ak-vsec.ak-solo .ak-vswh,.ak-vsec.ak-solo .ak-vdots{display:none!important}
/* Sin miniaturas: la portada del cuadro (fondo del contenedor) lleva un botón de play y un clic inicia el video */
.ak-vsec.ak-nothumbs .ak-vp{cursor:pointer}
.ak-vp .ak-vbig{display:none}
.ak-vsec.ak-nothumbs .ak-vp:not(.ak-on) .ak-vbig{display:grid;place-items:center;position:absolute;z-index:3;left:50%;top:50%;width:84px;height:84px;margin:-42px 0 0 -42px;border-radius:50%;background:#FFBB03;box-shadow:0 0 0 10px rgba(255,187,3,.25),0 10px 30px rgba(0,0,0,.45);pointer-events:auto;transition:transform .25s}
.ak-vsec.ak-nothumbs .ak-vp:not(.ak-on):hover .ak-vbig{transform:scale(1.08)}
.ak-vp .ak-vbig svg{width:34px;height:34px;margin-left:5px;fill:#15262F}
@media (max-width:767px){.ak-vsec.ak-nothumbs .ak-vp:not(.ak-on) .ak-vbig{width:64px;height:64px;margin:-32px 0 0 -32px}.ak-vp .ak-vbig svg{width:26px;height:26px;margin-left:4px}}
@media (max-width:1024px){
 .ak-vp .ak-vnav{display:grid;place-items:center;position:absolute;z-index:3;top:50%;width:34px;height:34px;margin-top:-17px;border-radius:50%;background:rgba(7,9,8,.55);color:#fff;font:600 20px/1 Arial,sans-serif;pointer-events:auto}
 .ak-vp .ak-vpv{left:8px}.ak-vp .ak-vnx{right:8px}
 .ak-vswh{display:block;position:absolute;z-index:3;left:50%;top:14px;transform:translateX(-50%);font:500 10px/1 Inter,Arial,sans-serif;letter-spacing:1.5px;text-transform:uppercase;color:#fff;background:rgba(7,9,8,.55);padding:6px 10px;border-radius:20px;white-space:nowrap;transition:opacity .4s}
 .ak-vswh.ak-off{opacity:0}
}
@media (max-width:767px){
 .ak-vsec .ak-vp{aspect-ratio:398/400}
 .ak-vdots{order:7;display:flex;justify-content:center;gap:6px;margin-top:22px}
 .ak-vdots i{cursor:pointer;width:10px;height:10px;border-radius:50%;border:1px solid #FFBB03;box-sizing:border-box}
 .ak-vdots i.ak-on{background:#FFBB03}
}

