.joinchat{--ch:206;--cs:81%;--cl:28%;--bw:1}
/*# sourceURL=joinchat-inline-css */

/* inline */


#gov-lr-overlay {

    display: none;

    position: fixed;

    top: 0;
    left: 0;
    right: 0;
    bottom: 0;

    width: 100%;
    height: 100%;

    background: rgba(0,0,0,.65);

    z-index: 999999;

    align-items: center;
    justify-content: center;

    padding: 20px;

    box-sizing: border-box;

}


#gov-lr-popup {

    width: 100%;
    max-width: 520px;

    background: #ffffff;

    border-radius: 18px;

    padding: 40px 35px;

    box-sizing: border-box;

    text-align: center;

    box-shadow:
        0 30px 80px rgba(0,0,0,.30);

    animation:
        govLRAnimation .30s ease;

}


.gov-lr-check {

    width: 72px;
    height: 72px;

    margin:
        0 auto 20px auto;

    border-radius: 50%;

    background: #ffc800;

    display: flex;

    align-items: center;
    justify-content: center;

    font-size: 36px;

    font-weight: 800;

    color: #000;

}


#gov-lr-popup h2 {

    margin:
        0 0 12px 0;

    font-size: 27px;

    line-height: 1.2;

    font-weight: 700;

    color: #111111;

}


#gov-lr-popup p {

    font-size: 15px;

    line-height: 1.6;

    color: #555555;

    margin:
        8px 0;

}


.gov-lr-code-label {

    margin-top: 20px !important;

    font-weight: 600;

    color: #222 !important;

}


#gov-lr-code {

    margin:
        12px 0 20px 0;

    padding:
        17px 15px;

    border-radius: 10px;

    background: #f5f5f5;

    border:
        2px dashed #ffc800;

    font-size: 24px;

    line-height: 1.2;

    font-weight: 800;

    letter-spacing: .6px;

    color: #111;

    user-select: all;

}


.gov-lr-buttons {

    display: flex;

    justify-content: center;

    gap: 10px;

    margin-top: 25px;

}


.gov-lr-button {

    border: none;

    border-radius: 8px;

    padding:
        13px 22px;

    font-size: 14px;

    font-weight: 600;

    cursor: pointer;

}


#gov-lr-copy {

    background: #ffc800;

    color: #111;

}


#gov-lr-close {

    background: #111;

    color: #fff;

}


@keyframes govLRAnimation {

    from {

        opacity: 0;

        transform:
            translateY(20px)
            scale(.96);

    }

    to {

        opacity: 1;

        transform:
            translateY(0)
            scale(1);

    }

}


@media(max-width: 600px) {

    #gov-lr-popup {

        padding:
            32px 20px;

    }


    #gov-lr-popup h2 {

        font-size: 23px;

    }


    #gov-lr-code {

        font-size: 19px;

    }


    .gov-lr-buttons {

        flex-direction: column;

    }

}

